const snapshot = [
  { material: 'TG11', description: 'Regular trading', handlingPolicy: 'STANDARD', onHand: 8, reorderPoint: 25, targetStock: 60, openDemand: 12 },
  { material: 'TG12', description: 'Reorder-point trading', handlingPolicy: 'STANDARD', onHand: 3, reorderPoint: 20, targetStock: 50, openDemand: 8 },
  { material: 'TG20', description: 'Serialized goods', handlingPolicy: 'SERIAL', onHand: 1, reorderPoint: 4, targetStock: 10, openDemand: 2 },
  { material: 'TG21', description: 'FIFO batch goods', handlingPolicy: 'BATCH_FIFO', onHand: 4, reorderPoint: 12, targetStock: 30, openDemand: 6 },
  { material: 'TG22', description: 'Expiry-managed batch goods', handlingPolicy: 'BATCH_EXPIRY', onHand: 2, reorderPoint: 10, targetStock: 24, openDemand: 8 },
  { material: 'TG24', description: 'Advanced receiving goods', handlingPolicy: 'ADVANCED_RECEIVING', onHand: 0, reorderPoint: 5, targetStock: 12, openDemand: 4 },
  { material: 'TG25', description: 'Advanced receiving goods', handlingPolicy: 'ADVANCED_RECEIVING', onHand: 2, reorderPoint: 6, targetStock: 15, openDemand: 3 },
];
return snapshot.map((row) => {
  const projectedAvailable = row.onHand - row.openDemand;
  const shouldReplenish = projectedAvailable < row.reorderPoint;
  const proposedQuantity = shouldReplenish ? Math.max(1, row.targetStock - projectedAvailable) : 0;
  const risk = projectedAvailable <= 0 ? 'CRITICAL' : projectedAvailable < row.reorderPoint / 2 ? 'HIGH' : 'MEDIUM';
  return { json: { ...row, projectedAvailable, shouldReplenish, proposedQuantity, risk, decisionRule: 'targetStock - (onHand - openDemand)' } };
});

const proposals = $input.all().map((item) => item.json).filter((row) => row.shouldReplenish);
const groups = [
  { code: 'STD', ref: 'ATLR-20260822-301', date: '20260910', policies: ['STANDARD'] },
  { code: 'SER', ref: 'ATLR-20260822-302', date: '20260912', policies: ['SERIAL'] },
  { code: 'FIFO', ref: 'ATLR-20260822-303', date: '20260914', policies: ['BATCH_FIFO'] },
  { code: 'EXP', ref: 'ATLR-20260822-304', date: '20260914', policies: ['BATCH_EXPIRY'] },
  { code: 'ASR', ref: 'ATLR-20260822-305', date: '20260916', policies: ['ADVANCED_RECEIVING'] },
];
const escapeXml = (value) => String(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll("'", '&apos;');
const control = `<EDI_DC40 SEGMENT='1'><TABNAM>EDI_DC40</TABNAM><DIRECT>2</DIRECT><DOCNUM></DOCNUM><MESTYP>ORDERS</MESTYP><IDOCTYP>ORDERS05</IDOCTYP><CIMTYP></CIMTYP><SNDPOR>N8NIDOC</SNDPOR><SNDPRT>LS</SNDPRT><SNDPRN>N8NIDOC</SNDPRN><RCVPOR>SAPA4H</RCVPOR><RCVPRT>LS</RCVPRT><RCVPRN>A4HCLNT250</RCVPRN></EDI_DC40>`;
return groups.map((group) => {
  const lines = proposals.filter((row) => group.policies.includes(row.handlingPolicy));
  const itemXml = lines.map((row, index) => {
    const position = String((index + 1) * 10).padStart(6, '0');
    return `<E1EDP01 SEGMENT='1'><POSEX>${position}</POSEX><MENGE>${row.proposedQuantity}</MENGE><MENEE>PCE</MENEE><E1EDP19 SEGMENT='1'><QUALF>002</QUALF><IDTNR>${escapeXml(row.material)}</IDTNR></E1EDP19><E1EDP20 SEGMENT='1'><WMENG>${row.proposedQuantity}</WMENG><EDATU>${group.date}</EDATU></E1EDP20></E1EDP01>`;
  }).join('');
  const idocXml = `<ORDERS05><IDOC BEGIN='1'>${control}<E1EDK01 SEGMENT='1'><ACTION>001</ACTION></E1EDK01><E1EDK14 SEGMENT='1'><QUALF>006</QUALF><ORGID>00</ORGID></E1EDK14><E1EDK14 SEGMENT='1'><QUALF>007</QUALF><ORGID>10</ORGID></E1EDK14><E1EDK14 SEGMENT='1'><QUALF>008</QUALF><ORGID>1710</ORGID></E1EDK14><E1EDK14 SEGMENT='1'><QUALF>012</QUALF><ORGID>OR1</ORGID></E1EDK14><E1EDK03 SEGMENT='1'><IDDAT>002</IDDAT><DATUM>${group.date}</DATUM></E1EDK03><E1EDKA1 SEGMENT='1'><PARVW>AG</PARVW><PARTN>0017100001</PARTN></E1EDKA1><E1EDK02 SEGMENT='1'><QUALF>001</QUALF><BELNR>${group.ref}</BELNR><DATUM>20260822</DATUM></E1EDK02>${itemXml}</IDOC></ORDERS05>`;
  const businessKey = `A4H250-ATLR-REPL-${group.code}-20260822-v1`;
  return { json: { idempotencyKey: businessKey, writeConfirmation: `SEND submitPurchaseOrderIdoc ${businessKey}`, replenishmentWave: group.code, businessRef: group.ref, requestedDate: group.date, decisionCount: lines.length, totalQuantity: lines.reduce((sum, row) => sum + row.proposedQuantity, 0), highestRisk: lines.some((row) => row.risk === 'CRITICAL') ? 'CRITICAL' : 'HIGH', items: lines, idocXml } };
});
